(function(){class i{constructor(e){this.el=e,this.triggers=Array.from(e.querySelectorAll(".accordion-trigger")),this.allowMultiple=!1,this.init()}init(){this.triggers.forEach(e=>{e.addEventListener("click",t=>this.toggle(t.currentTarget)),e.addEventListener("keydown",t=>this.handleKeyDown(t))})}toggle(e){const t=e.getAttribute("aria-expanded")==="true";document.getElementById(e.getAttribute("aria-controls")),!this.allowMultiple&&!t&&this.triggers.forEach(s=>{s!==e&&s.getAttribute("aria-expanded")==="true"&&this.close(s)}),t?this.close(e):this.open(e)}open(e){const t=document.getElementById(e.getAttribute("aria-controls"));e.setAttribute("aria-expanded","true"),t.classList.remove("accordion-panel--hidden")}close(e){const t=document.getElementById(e.getAttribute("aria-controls"));e.setAttribute("aria-expanded","false"),t.classList.add("accordion-panel--hidden")}handleKeyDown(e){const t=e.currentTarget,s=this.triggers.indexOf(t);switch(e.key){case"ArrowDown":e.preventDefault(),this.focusNext(s);break;case"ArrowUp":e.preventDefault(),this.focusPrevious(s);break;case"Home":e.preventDefault(),this.triggers[0].focus();break;case"End":e.preventDefault(),this.triggers[this.triggers.length-1].focus();break}}focusNext(e){const t=e===this.triggers.length-1?0:e+1;this.triggers[t].focus()}focusPrevious(e){const t=e===0?this.triggers.length-1:e-1;this.triggers[t].focus()}}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".accordion").forEach(e=>{new i(e)})})})();
